#!/usr/bin/env bash
# G2 measurement driver (plan 02 WP-8): cterm daemon/standalone vs foot in a nested `crucible --winit`, plus the end-to-end reversed-arrival test.
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/g2/g2.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'g2.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
set -euo pipefail

usage() {
	cat <<'USAGE'
Usage: g2.sh [--help|-h] [--build|--version] [LEG...]

Legs (default: ff mem reshow info e2e): ff, mem, reshow, info, e2e, smoke, summarize, rsummarize.
Every leg runs in its own fresh nested `crucible --winit` launched through `crucible msg run-on` into a scratch workspace (scratch-cterm-<driver>-<pid>; override with CTERM_SCRATCH_WS, which must start with scratch-; the live CDE_SOCKET is required; parent WAYLAND_DISPLAY=/run/user/1001/wayland-1) with
XDG_RUNTIME_DIR, XDG_STATE_HOME, XDG_CONFIG_HOME and XDG_DATA_HOME in scratch (/tmp/cde-g2w), so the nested daemon socket and
daemon.log never touch the live ones. cterm is spawned DIRECTLY by CDE (never through scripts/g1/term.sh, which defeats the
basename-gated grant minting); every mode=auto subject is asserted to be in daemon mode (resident `cterm daemon`, shells in its subtree,
clients with no children) and a silent standalone fallback aborts the session as a harness failure. Only pids this script recorded
(with their start time) are ever signalled.

  ff         first frame, median of 5 per batch: warm `cterm -o mode=auto` daemon (daemon started with WAYLAND_DEBUG=1, one window open),
             `cterm -o mode=standalone` and foot (both through a scratch exec wrapper that sets WAYLAND_DEBUG=1; no grant is needed there).
  mem        PSS ladder 1/5/20 windows stacked in one pane for foot, standalone and auto (daemon subtree + each client); daemon idle
             PSS (zero windows) for auto. Raw: shm PSS and Rss kept apart for the normalisation done by `summarize`.
  reshow     re-show content check (CTERM_DEBUG_FRAME_SUM=1): stack 4 windows, cycle the stack, compare each resume frame-sum with its
             frame-sum-full, for auto and standalone.
  info       50 MB cat (3 runs) standalone vs auto; daemon idle CPU with 2 windows over G2_IDLE_S seconds.
  e2e        reversed-arrival end to end: crafted two-terminal workspace restored by the nested CDE, daemon with
             CTERM_DEBUG_OPEN_DELAY_MS, then `crucible msg save`, `crucible mem`, `crucible msg close-pid <C1>`.
  smoke      one auto session, 3 windows, assert daemon mode, print the process tree (quick check).
  summarize  read target/g2/g2-*.raw and print the G2 table against the thresholds (target/g2/g2-summary.txt).
  rsummarize read $G2_OUT/g2-{ff,mem,cond}.raw and print the re-measurement tables (ff per subject and batch, leg (iii) with foot-server, COND lines) to $G2_OUT/remeasure-summary.txt.

Re-measurement (2026-11-05): G2_OUT=target/g2/remeasure G2_FF_SUBJECTS="foot-wl 0.2.0=<bin> 0.3.0=<bin>@standalone auto" G2_MEM_SUBJECTS="foot foot-server standalone auto" g2.sh ff mem rsummarize.
  G2_FF_SUBJECTS entries: foot-wl | standalone-wl | auto | LABEL=PATH[@MODE] (cterm binary PATH through the WAYLAND_DEBUG wrapper, `-o mode=MODE` only when @MODE is given: pre-0.3.0 builds have no mode key).
  G2_MEM_SUBJECTS entries: foot | standalone | auto | foot-server (`foot --server` inside the nested display + footclient as CDE terminal; server subtree + the footclients).
  Conditions: every nested session records COND lines (date, /proc/loadavg, PSI cpu/memory/io some avg10,avg60, live outputs enabled/dpms/preferred mode) at start and end into the leg raw file, and waits up to G2_CPU_PSI_WAIT_S (60) for CPU PSI avg10 <= G2_CPU_PSI_MAX (5) first (COND_WAIT line).

Output: raw lines in target/g2/g2-<leg>.raw (appended per run; delete to start over) and per-session logs in target/g2/logs/.
Environment (defaults): G2_CRUCIBLE (crucible-dev-env/target/release/crucible), G2_CT (target/release/cterm), G2_FOOT (~/.local/bin/foot),
G2_FOOT_INI (~/.config/foot/foot.ini), G2_PARENT_WL (/run/user/1001/wayland-1), G2_GAP (10), G2_BATCHES (3), G2_SETTLE_S (4), G2_FF_RUNS (5),
G2_N_LO (5), G2_N_HI (20), G2_IDLE_S (60), G2_DELAY_MS (800), G2_BLINK (true; false disables cursor blink in the reshow leg), G2_WAIT_S (120).
G2_OUT (target/g2), G2_FF_WARM (1; 0 = no window open before the timed runs, as in G1), G2_FF_SUBJECTS, G2_MEM_SUBJECTS, G2_CPU_PSI_MAX (5), G2_CPU_PSI_WAIT_S (60), G2_WAIT_DISPLAY_S (0), G2_SKIP_DISPLAY_CHECK (0).
Bash reasons: arrays for argv and pid lists, process substitution, local variables, trap cleanup, BASH_SOURCE.
USAGE
}

# shellcheck source-path=SCRIPTDIR source=../lib/build-id.sh
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/build-id.sh"
# shellcheck source-path=SCRIPTDIR source=../lib/run-on.sh
. "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../lib/run-on.sh"
case " $* " in *" --help "* | *" -h "*) usage; exit 0 ;; esac
build_flags "${BASH_SOURCE[0]}" "$@"

LEGS=("$@")
[ "$#" -gt 0 ] || LEGS=(ff mem reshow info e2e)
for s in "${LEGS[@]}"; do
	case $s in ff | mem | reshow | info | e2e | smoke | summarize | rsummarize) ;; *) echo "g2.sh: unknown leg: $s" >&2; usage >&2; exit 2 ;; esac
done

HERE=$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd -P)
R=$(cd "$HERE/../.." && pwd -P)
CDE=crucible-dev-env
BIN=${G2_CRUCIBLE:-$CDE/target/release/crucible}
CT=${G2_CT:-$R/target/release/cterm}
FOOT=$(readlink -f "${G2_FOOT:-$HOME/.local/bin/foot}")
FOOT_INI=${G2_FOOT_INI:-$HOME/.config/foot/foot.ini}
PARENT_WL=${G2_PARENT_WL:-/run/user/1001/wayland-1}
GAP=${G2_GAP:-10}
BATCHES=${G2_BATCHES:-3}
SETTLE=${G2_SETTLE_S:-4}
FF_RUNS=${G2_FF_RUNS:-5}
N_LO=${G2_N_LO:-5}
N_HI=${G2_N_HI:-20}
IDLE_S=${G2_IDLE_S:-60}
DELAY_MS=${G2_DELAY_MS:-800}
BLINK=${G2_BLINK:-true}
WAIT_S=${G2_WAIT_S:-120}
OUT=${G2_OUT:-$R/target/g2}
FOOTCLIENT=$(dirname "$FOOT")/footclient
FF_WARM=${G2_FF_WARM:-1}
FF_SUBJECTS=${G2_FF_SUBJECTS:-"foot-wl standalone-wl auto"}
MEM_SUBJECTS=${G2_MEM_SUBJECTS:-"foot standalone auto"}
CPU_PSI_MAX=${G2_CPU_PSI_MAX:-5}
CPU_PSI_WAIT_S=${G2_CPU_PSI_WAIT_S:-60}
COND_RAW=""
W=/tmp/cde-g2w
BIG=$R/target/g1/50mb.txt
LIVE_RT=/run/user/1001
mkdir -p "$OUT/logs"

die() { echo "g2.sh: $*" >&2; exit 1; }

now() { perl -MTime::HiRes=time -e 'printf "%.6f\n", time'; }
median() { sort -n | awk '{a[NR]=$1} END{ if(NR==0){print "NA"} else if(NR%2){print a[(NR+1)/2]} else {printf "%.3f\n",(a[NR/2]+a[NR/2+1])/2} }'; }

starttime() { perl -e 'open(F,"<","/proc/$ARGV[0]/stat") or exit 1; my $s=<F>; $s=~/\) (.*)$/ or exit 1; my @f=split / /,$1; print $f[19]' "$1"; }
rec() { local st; st=$(starttime "$1") || return 0; echo "$1 $st" >>"$W/pids"; }
# signal only recorded pids whose start time still matches (pid reuse safe)
killrec() {
	local p st cur
	[ -f "$W/pids" ] || return 0
	while read -r p st; do
		cur=$(starttime "$p" 2>/dev/null) || continue
		if [ "$cur" = "$st" ]; then kill "$p" 2>/dev/null || true; fi
	done <"$W/pids"
	return 0
}
kids_of() { perl -e 'my $r=shift; opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){ open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/^\d+ \(.*\) \S (\d+)/ or next; print "$p\n" if $1==$r }' "$1"; }
alive() { [ -n "${1:-}" ] && [ -d "/proc/$1" ] && ! grep -q '^State:.*Z' "/proc/$1/status" 2>/dev/null; }

# "nonshm_kB shm_pss_kB shm_rss_kB nprocs" summed over the subtrees of the pids given (smaps; memfd and /dev/shm mappings are shm)
pss_of() {
	perl -e '
  my %kids; opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){ open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/^\d+ \(.*\) \S (\d+)/ or next; push @{$kids{$1}},$p }
  my %seen; my @q=@ARGV; my ($ns,$sp,$sr,$n)=(0,0,0,0);
  while(defined(my $p=shift @q)){ next if $seen{$p}++; push @q,@{$kids{$p}||[]};
    open(F,"<","/proc/$p/smaps") or next; $n++; my $shm=0;
    while(<F>){ if(/^[0-9a-f]+-[0-9a-f]+ \S+ \S+ \S+ \d+\s*(.*)$/){ $shm = $1 =~ m{^/memfd:|^/dev/shm/} ? 1 : 0 }
      elsif(/^Pss:\s+(\d+)/){ if($shm){$sp+=$1}else{$ns+=$1} } elsif(/^Rss:\s+(\d+)/ && $shm){ $sr+=$1 } }
    close F }
  print "$ns $sp $sr $n\n"' "$@"
}
# utime+stime ticks over the subtrees of the pids given
ticks_of() {
	perl -e '
  my %kids; opendir(D,"/proc"); for my $p (grep /^\d+$/, readdir D){ open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/^\d+ \(.*\) \S (\d+)/ or next; push @{$kids{$1}},$p }
  my %seen; my @q=@ARGV; my $tk=0;
  while(defined(my $p=shift @q)){ next if $seen{$p}++; push @q,@{$kids{$p}||[]};
    open(F,"<","/proc/$p/stat") or next; my $s=<F>; close F; $s=~/\) (.*)$/ and do { my @f=split / /,$1; $tk+=$f[11]+$f[12] } }
  print "$tk\n"' "$@"
}

# first buffer-bearing wl_surface.commit after ack_configure on a NEW xdg_surface (created after t0), ms after t0 (empty if none yet)
first_frame_ms() {
	perl -e '
  my ($t0,$f)=@ARGV; my $M=4294967296; my $t0u=int($t0*1e6)%$M; my (%x2w,%ack,%att); my $best;
  open(F,"<",$f) or exit 0;
  while(<F>){ next unless /^\[\s*([\d.]+)\](?:\[\w+\])?\s+(?:\{[^}]*\}\s+)?->\s+(\S+)\.(\w+)\((.*)\)/; my($ts,$obj,$req,$a)=($1,$2,$3,$4);
    my $d=($ts*1000-$t0u); $d+=$M while $d<0; $d-=$M while $d>=$M; next if $d>60e6;
    if($req eq "get_xdg_surface" && $a=~/xdg_surface[#@](\d+).*wl_surface[#@](\d+)/){ $x2w{$1}=$2 }
    elsif($req eq "ack_configure" && $obj=~/[#@](\d+)$/ && defined $x2w{$1}){ $ack{$x2w{$1}}=1 }
    elsif($req eq "attach" && $obj=~/[#@](\d+)$/ && $ack{$1} && $a!~/^nil/){ $att{$1}=1 }
    elsif($req eq "commit" && $obj=~/[#@](\d+)$/ && $att{$1}){ $best=$d if !defined($best)||$d<$best; last } }
  printf "%.1f\n",$best/1000 if defined $best' "$1" "$2"
}

# ---------------------------------------------------------------- nested compositor sessions
SUBJ_PROG="" SUBJ_MODE=""
T="" CPID="" DPID="" DISP="" PROGEXE="" KIND="" TAG=""
CLIENTS=()
KNOWN=()
XENV=() # extra env words for the compositor (inherited by every spawn)

cleanup() {
	if alive "$CPID"; then run_on_close "$CPID"; fi
	killrec
	[ -z "$T" ] || rm -rf "$T"
	return 0
}
trap cleanup EXIT

msg() { CDE_SOCKET=$(ls "$T"/run/cde/*.sock | head -1) "$BIN" msg "$@"; }

write_ct_config() {
	cat >"$T/config/crucible-term/config.kdl" <<KDL
font "Bitstream Vera Sans Mono" size=14
colors {
    foreground "#c5c8c6"
    background "#000000"
    cursor "#c5c8c6"
    alpha 0.8
    palette 0 "#282a2e"
    palette 1 "#a54242"
    palette 2 "#649440"
    palette 3 "#de935f"
    palette 4 "#5f819d"
    palette 5 "#85678f"
    palette 6 "#5e8d87"
    palette 7 "#707880"
    palette 8 "#373b41"
    palette 9 "#cc6666"
    palette 10 "#8abd68"
    palette 11 "#f0c674"
    palette 12 "#81a2be"
    palette 13 "#b294bb"
    palette 14 "#8abeb7"
    palette 15 "#c5c8c6"
}
scrollback lines=10000
pad 2 2
center
cursor shape="block" blink=#$BLINK
KDL
}

# the nested compositor's wayland socket name (the *.lock files are skipped)
# $! may be a forking setsid: the compositor is it or its child running $BIN
real_cpid() { # pid [exe, default $BIN]
	local p=$1 c x=${2:-$BIN}
	if [ "$(readlink -f "/proc/$p/exe" 2>/dev/null)" = "$(readlink -f "$x")" ]; then echo "$p"; return 0; fi
	for c in $(kids_of "$p"); do
		if [ "$(readlink -f "/proc/$c/exe" 2>/dev/null)" = "$(readlink -f "$x")" ]; then echo "$c"; return 0; fi
	done
	echo "$p"
}

# conditions: one COND line (date, load, PSI avg10/avg60, live outputs enabled/dpms and preferred mode) per call into $COND_RAW (default $OUT/g2-cond.raw)
cond_psi() { awk -v k="$2" '$1==k {print $2 "," $3}' "/proc/pressure/$1" 2>/dev/null | tr "\n" " " | sed "s/avg10=//;s/avg60=//;s/ $//"; }
cond_outputs() {
	local d out=""
	for d in /sys/class/drm/card*-*; do
		[ "$(cat "$d/status" 2>/dev/null)" = connected ] || continue
		out="$out$(basename "$d")=$(cat "$d/enabled" 2>/dev/null)/$(cat "$d/dpms" 2>/dev/null)/$(head -1 "$d/modes" 2>/dev/null) "
	done
	echo "${out% }"
}
cond_record() { # label
	echo "COND label=$1 date=$(date -Is) loadavg=\"$(cut -d" " -f1-4 /proc/loadavg)\" cpu_some_avg10_avg60=$(cond_psi cpu some) mem_some_avg10_avg60=$(cond_psi memory some) io_some_avg10_avg60=$(cond_psi io some) outputs=\"$(cond_outputs)\"" | tee -a "${COND_RAW:-$OUT/g2-cond.raw}"
}
# wait up to CPU_PSI_WAIT_S for the CPU pressure avg10 (some) to fall to CPU_PSI_MAX percent; record the wait
wait_calm() { # label
	local w=0 a
	a=$(awk '$1=="some" {sub("avg10=","",$2); print $2}' /proc/pressure/cpu)
	while awk -v a="$a" -v m="$CPU_PSI_MAX" 'BEGIN{exit !(a>m)}' && [ "$w" -lt "$CPU_PSI_WAIT_S" ]; do
		sleep 5
		w=$((w + 5))
		a=$(awk '$1=="some" {sub("avg10=","",$2); print $2}' /proc/pressure/cpu)
	done
	echo "COND_WAIT label=$1 waited_s=$w cpu_avg10_now=$a limit=$CPU_PSI_MAX" | tee -a "${COND_RAW:-$OUT/g2-cond.raw}"
}

# terminal children the compositor started itself (the overlay host): never counted as windows
snapshot_known() {
	local p
	KNOWN=()
	for p in $(kids_of "$CPID"); do
		if [ "$(readlink -f "/proc/$p/exe" 2>/dev/null)" = "$PROGEXE" ]; then KNOWN+=("$p"); rec "$p"; fi
	done
}

nested_display() {
	local f
	for f in "$T"/run/wayland-*; do
		case $f in *.lock) ;; *) basename "$f"; return 0 ;; esac
	done
	return 1
}

# `foot --server` inside the nested display with the scratch foot.ini; DPID is its pid (recorded), socket $T/run/foot-$DISP.sock
start_foot_server() {
	[ -x "$FOOTCLIENT" ] || { echo "STOP foot-server: footclient not found at $FOOTCLIENT"; return 1; }
	env XDG_CONFIG_HOME="$T/config" XDG_STATE_HOME="$T/state" XDG_RUNTIME_DIR="$T/run" WAYLAND_DISPLAY="$DISP" setsid "$FOOT" --server >/dev/null 2>"$T/foot-server.log" &
	DPID=$(real_cpid "$!" "$FOOT")
	rec "$!"
	rec "$DPID"
	local i
	for i in $(seq 1 50); do
		[ -S "$T/run/foot-$DISP.sock" ] && break
		sleep 0.2
	done
	[ -S "$T/run/foot-$DISP.sock" ] || { echo "foot --server did not come up"; cat "$T/foot-server.log"; return 1; }
	echo "foot server pid $DPID socket $T/run/foot-$DISP.sock"
}

# cde_start TAG KIND: KIND is foot | standalone | auto | foot-server (direct spawn; foot-server = `foot --server` started in the nested display + footclient as the terminal),
# or foot-wl | standalone-wl | ct-wl (scratch exec wrapper, WAYLAND_DEBUG on; ct-wl runs SUBJ_PROG with `-o mode=SUBJ_MODE` unless SUBJ_MODE is empty)
cde_start() {
	TAG=$1 KIND=$2
	wait_calm "$TAG"
	cond_record "$TAG start"
	T=$W/$TAG
	rm -rf "$T"
	mkdir -p "$T/config/cde" "$T/config/crucible-term" "$T/config/foot" "$T/state/crucible-term" "$T/data" "$T/run"
	chmod 700 "$T/run"
	CLIENTS=() DPID="" CPID=""
	write_ct_config
	cp "$FOOT_INI" "$T/config/foot/foot.ini"
	local prog targs="" mode=""
	case $KIND in
	foot | foot-wl) prog=$FOOT ;;
	foot-server) prog=$FOOTCLIENT ;;
	ct-wl) prog=$SUBJ_PROG mode=$SUBJ_MODE ;;
	standalone | standalone-wl) prog=$CT mode=standalone ;;
	auto) prog=$CT mode=auto ;;
	*) die "bad kind $KIND" ;;
	esac
	PROGEXE=$(readlink -f "$prog")
	local term=$prog
	case $KIND in
	*-wl)
		term=$T/launch.sh
		printf '#!/bin/sh\nexec env WAYLAND_DEBUG=1 %s "$@" 2>"%s/wl.$$.log"\n' "$prog" "$T" >"$term"
		chmod +x "$term"
		;;
	foot-server)
		# the overlay host CDE starts at launch must not join the server as a window: the gate file opens after launch (the others exclude it as a separate process)
		term=$T/launch.sh
		printf '#!/bin/sh\n[ -e "%s/go" ] || exit 1\nexec %s "$@"\n' "$T" "$prog" >"$term"
		chmod +x "$term"
		;;
	esac
	[ -z "$mode" ] || targs=' "-o" "mode='$mode'"'
	cat >"$T/config/cde/config.kdl" <<KDL
tiling {
    terminal gap=(px)$GAP ring=(px)2 ring-inset=(px)4 frame="#3a3a3a"
    terminal-args "-o" "pad={gap}x{gap} center"$targs
}
terminal "$term" exec-flag="-e"
KDL
	run_on_launch g2 "$T" "$T/log" "${XENV[@]}" XDG_CONFIG_HOME="$T/config" XDG_STATE_HOME="$T/state" XDG_DATA_HOME="$T/data" XDG_RUNTIME_DIR="$T/run" WAYLAND_DISPLAY="$PARENT_WL" -- "$BIN" --winit || return 1
	CPID=$(real_cpid "$RUN_ON_PID")
	rec "$RUN_ON_PID"
	rec "$CPID"
	local i
	for i in $(seq 1 60); do
		ls "$T"/run/cde/*.sock >/dev/null 2>&1 && ls "$T"/run/wayland-* >/dev/null 2>&1 && break
		sleep 0.2
	done
	alive "$CPID" || { echo "compositor died: see $T/log"; tail -5 "$T/log"; return 1; }
	DISP=$(nested_display)
	[ "$KIND" != foot-server ] || start_foot_server || return 1
	# Live-session safety: the nested display must not share the live daemon socket (keyed by display basename under XDG_RUNTIME_DIR).
	[ "$T/run" != "$LIVE_RT" ] || die "nested XDG_RUNTIME_DIR is the live one"
	if [ "$DISP" = wayland-1 ]; then
		echo "NOTE nested display basename is wayland-1 (same as live); the daemon socket stays separate because XDG_RUNTIME_DIR=$T/run != $LIVE_RT"
	fi
	[ ! -e "$LIVE_RT/cterm/$DISP.sock" ] || echo "NOTE a live cterm daemon socket exists at $LIVE_RT/cterm/$DISP.sock (untouched: nested XDG_RUNTIME_DIR differs)"
	echo "== $TAG kind=$KIND compositor pid $CPID display=$DISP runtime=$T/run"
	sleep 3
	snapshot_known
	[ "$KIND" != foot-server ] || : >"$T/go"
}

cde_stop() {
	local p
	cond_record "$TAG end"
	for p in "${CLIENTS[@]}"; do alive "$p" && kill "$p" 2>/dev/null || true; done
	sleep 1
	msg exec quit >/dev/null 2>&1 || true
	sleep 2
	if alive "$CPID"; then run_on_close "$CPID"; kill "$CPID" 2>/dev/null || true; fi
	alive "$DPID" && kill "$DPID" 2>/dev/null || true
	sleep 0.5
	cp "$T/log" "$OUT/logs/$TAG.compositor.log" 2>/dev/null || true
	cp "$T/state/crucible-term/daemon.log" "$OUT/logs/$TAG.daemon.log" 2>/dev/null || true
	rm -rf "$T"
	T="" CLIENTS=() DPID="" CPID=""
}

# daemon pid from its log line "daemon: pid N listening"
daemon_pid() { sed -n 's/^crucible-term: daemon: pid \([0-9]*\) listening.*/\1/p' "$T/state/crucible-term/daemon.log" 2>/dev/null | tail -1; }

# start the daemon by hand (so WAYLAND_DEBUG can be set for it); readiness = its socket
start_daemon() { # [env words...]
	env "$@" XDG_CONFIG_HOME="$T/config" XDG_STATE_HOME="$T/state" XDG_RUNTIME_DIR="$T/run" WAYLAND_DISPLAY="$DISP" setsid "$CT" daemon >/dev/null 2>>"$T/state/crucible-term/daemon.log" &
	local i
	for i in $(seq 1 50); do
		[ -S "$T/run/cterm/$DISP.sock" ] && break
		sleep 0.2
	done
	[ -S "$T/run/cterm/$DISP.sock" ] || { echo "daemon did not come up"; tail -3 "$T/state/crucible-term/daemon.log"; return 1; }
	DPID=$(daemon_pid)
	[ -n "$DPID" ] || die "no daemon pid in daemon.log"
	rec "$DPID"
	echo "daemon pid $DPID"
}

NEWPID=""
# spawn one window with `run-terminal`; sets NEWPID to the new client pid (a child of the compositor running the terminal binary)
spawn_win() { # [action words, default: exec run-terminal]
	local i p known c
	NEWPID=""
	[ "$#" -gt 0 ] || set -- exec run-terminal
	for i in $(seq 1 10); do
		msg "$@" >/dev/null 2>"$T/msg.err" && break
		[ "$i" -lt 10 ] || { cat "$T/msg.err" >&2; return 1; }
		sleep 1
	done
	for i in $(seq 1 100); do
		for p in $(kids_of "$CPID"); do
			[ "$(readlink -f "/proc/$p/exe" 2>/dev/null)" = "$PROGEXE" ] || continue
			known=0
			for c in "${CLIENTS[@]}"; do [ "$c" = "$p" ] && known=1; done
			for c in "${KNOWN[@]}"; do [ "$c" = "$p" ] && known=1; done
			[ "$known" = 0 ] || continue
			NEWPID=$p
			break 2
		done
		sleep 0.1
	done
	[ -n "$NEWPID" ] || return 1
	CLIENTS+=("$NEWPID")
	rec "$NEWPID"
}

nshells() { kids_of "$1" | wc -l; }

# foot --server mode: resident server (the recorded DPID), one shell per window in its subtree, footclients with no children
assert_server_mode() { # expected window count
	local want=$1 c
	alive "$DPID" || { echo "HARNESS FAILURE: foot server is not alive"; return 1; }
	[ "$(nshells "$DPID")" = "$want" ] || { echo "HARNESS FAILURE: foot server has $(nshells "$DPID") children, expected $want shells"; return 1; }
	for c in "${CLIENTS[@]}"; do
		alive "$c" || continue
		[ "$(nshells "$c")" = 0 ] || { echo "HARNESS FAILURE: footclient $c has a child"; return 1; }
	done
	echo "ASSERT server-mode ok: foot server pid $DPID shells=$want footclients=${#CLIENTS[@]} (none with children)"
}
# Daemon-mode assertion (c1 E3): resident `cterm daemon` (cmdline exactly "<ct>\0daemon\0"), not a child of any client, one shell per window
# in its subtree, and no client has a child. A silent standalone fallback is a harness failure.
assert_daemon_mode() { # expected window count
	local want=$1 cmd c p
	DPID=$(daemon_pid)
	[ -n "$DPID" ] && alive "$DPID" || { echo "HARNESS FAILURE: no resident daemon (auto fell back to standalone?)"; return 1; }
	cmd=$(tr '\0' ' ' <"/proc/$DPID/cmdline")
	[ "$cmd" = "$CT daemon " ] || { echo "HARNESS FAILURE: daemon cmdline is '$cmd'"; return 1; }
	p=$(awk '{print $4}' "/proc/$DPID/stat")
	for c in "${CLIENTS[@]}"; do [ "$c" != "$p" ] || { echo "HARNESS FAILURE: daemon is a child of client $c"; return 1; }; done
	[ "$(nshells "$DPID")" = "$want" ] || { echo "HARNESS FAILURE: daemon has $(nshells "$DPID") children, expected $want shells"; return 1; }
	for c in "${CLIENTS[@]}"; do
		alive "$c" || continue
		[ "$(nshells "$c")" = 0 ] || { echo "HARNESS FAILURE: client $c has a child (standalone window)"; return 1; }
	done
	echo "ASSERT daemon-mode ok: daemon pid $DPID cmdline='$cmd' shells=$want clients=${#CLIENTS[@]} (none with children)"
}
assert_standalone_mode() { # expected window count
	local want=$1 c n=0
	for c in "${CLIENTS[@]}"; do [ "$(nshells "$c")" = 1 ] && n=$((n + 1)); done
	[ "$n" = "$want" ] || { echo "HARNESS FAILURE: $n of $want clients own a shell"; return 1; }
	[ ! -S "$T/run/cterm/$DISP.sock" ] || { echo "HARNESS FAILURE: a daemon socket exists in standalone mode"; return 1; }
	echo "ASSERT standalone-mode ok: $want clients each own a shell, no daemon socket"
}

# ---------------------------------------------------------------- legs
mem_row() { # batch subj n
	local b=$1 subj=$2 n=$3 pids=("${CLIENTS[@]}") ns sp sr np
	if [ "$KIND" = auto ]; then
		assert_daemon_mode "$n" || return 1
		pids=("$DPID" "${CLIENTS[@]}")
	elif [ "$KIND" = foot-server ]; then
		assert_server_mode "$n" || return 1
		pids=("$DPID" "${CLIENTS[@]}")
	elif [ "$KIND" = standalone ]; then
		assert_standalone_mode "$n" || return 1
	fi
	read -r ns sp sr np < <(pss_of "${pids[@]}")
	echo "MEM batch=$b subj=$subj n=$n nonshm=$ns shm_pss=$sp shm_rss=$sr procs=$np" | tee -a "$OUT/g2-mem.raw"
	if [ "$KIND" = auto ] || [ "$KIND" = foot-server ]; then
		read -r ns sp sr np < <(pss_of "$DPID")
		echo "DMEM batch=$b subj=$KIND-daemon n=$n nonshm=$ns shm_pss=$sp shm_rss=$sr procs=$np" | tee -a "$OUT/g2-mem.raw"
		read -r ns sp sr np < <(pss_of "${CLIENTS[@]}")
		echo "CMEM batch=$b subj=$KIND-clients n=$n nonshm=$ns shm_pss=$sp shm_rss=$sr procs=$np" | tee -a "$OUT/g2-mem.raw"
	fi
}

leg_mem_session() { # batch kind
	local b=$1 kind=$2 n
	XENV=()
	cde_start "mem-$kind-$b" "$kind" || { cde_stop; return 1; }
	if [ "$kind" = auto ] || [ "$kind" = foot-server ]; then
		[ "$kind" != auto ] || start_daemon
		sleep "$SETTLE"
		local ns sp sr np
		read -r ns sp sr np < <(pss_of "$DPID")
		echo "DMEM batch=$b subj=$kind-daemon n=0 nonshm=$ns shm_pss=$sp shm_rss=$sr procs=$np" | tee -a "$OUT/g2-mem.raw"
	fi
	for n in $(seq 1 "$N_HI"); do
		spawn_win || { echo "spawn $n failed"; cde_stop; return 1; }
		case $n in
		1 | "$N_LO" | "$N_HI")
			sleep "$SETTLE"
			mem_row "$b" "$kind" "$n" || { cde_stop; return 1; }
			;;
		esac
	done
	cde_stop
}

leg_mem() {
	local b k
	COND_RAW=$OUT/g2-mem.raw
	for b in $(seq 1 "$BATCHES"); do
		for k in $MEM_SUBJECTS; do leg_mem_session "$b" "$k" || echo "FAILED mem batch $b $k"; done
	done
}

leg_ff_session() { # batch subject; subject is foot-wl | standalone-wl | auto | LABEL=PATH[@MODE] (any cterm build through the wrapper; MODE empty = no -o mode)
	local b=$1 subj=$2 kind=$2 label=$2 i t0 lat lats="" f ps rest
	XENV=()
	SUBJ_PROG="" SUBJ_MODE=""
	case $subj in
	*=*)
		kind=ct-wl label=${subj%%=*} rest=${subj#*=}
		SUBJ_PROG=${rest%%@*}
		case $rest in *@*) SUBJ_MODE=${rest#*@} ;; esac
		[ -x "$SUBJ_PROG" ] || { echo "ff subject $label: missing $SUBJ_PROG"; return 1; }
		echo "SUBJECT $label path=$SUBJ_PROG mode=${SUBJ_MODE:-none} version=$("$SUBJ_PROG" --version 2>&1 | head -1)" | tee -a "$OUT/g2-ff.raw"
		;;
	esac
	cde_start "ff-$label-$b" "$kind" || { cde_stop; return 1; }
	if [ "$kind" = auto ]; then
		start_daemon WAYLAND_DEBUG=1
		f=$T/state/crucible-term/daemon.log
	fi
	if [ "$FF_WARM" = 1 ]; then
		spawn_win || { echo "warm window failed"; cde_stop; return 1; }
	fi
	sleep 3
	[ "$kind" != auto ] || assert_daemon_mode "$FF_WARM" || { cde_stop; return 1; }
	for i in $(seq 1 "$FF_RUNS"); do
		t0=$(now)
		spawn_win || { echo "spawn failed"; break; }
		ps=$NEWPID
		[ "$kind" = auto ] || f=$T/wl.$ps.log
		lat=""
		for _ in $(seq 1 100); do
			sleep 0.1
			lat=$(first_frame_ms "$t0" "$f" 2>/dev/null || true)
			[ -z "$lat" ] || break
		done
		echo "FF batch=$b subj=$label run=$i ms=${lat:-FAIL}" | tee -a "$OUT/g2-ff.raw"
		[ -z "$lat" ] || lats="$lats$lat"$'\n'
		kill "$ps" 2>/dev/null || true
		sleep 1.5
	done
	echo "FF_MEDIAN batch=$b subj=$label ms=$(printf '%s' "$lats" | median)" | tee -a "$OUT/g2-ff.raw"
	if [ "$kind" = auto ]; then cp "$f" "$OUT/logs/ff-auto-$b.daemon-wldebug.log" 2>/dev/null || true; fi
	cde_stop
}

leg_ff() {
	local b k
	COND_RAW=$OUT/g2-ff.raw
	for b in $(seq 1 "$BATCHES"); do
		for k in $FF_SUBJECTS; do leg_ff_session "$b" "$k" || echo "FAILED ff batch $b $k"; done
	done
}

# re-show check: parse the log text of the frame-sum hook
reshow_verdict() { # logfile kind
	perl -e '
  my ($f,$kind)=@ARGV; open(F,"<",$f) or die "$f: $!"; my (%last,%susp,$full,$pass)=((),(),0,0);
  while(<F>){
    if(/crucible-term: frame-sum: (\d+) (\d+) ([0-9a-f]{16})/){ $last{$1}=[$2,$3] }
    elsif(/crucible-term: frame-sum-full: (\d+) ([0-9a-f]{16})/){ my($id,$h)=($1,$2); $full++; my $l=$last{$id};
      my $ok = $l && $l->[1] eq $h; $pass++ if $ok;
      printf "RESHOW kind=%s term=%d first_seq=%s first=%s full=%s %s\n",$kind,$id,$l?$l->[0]:"none",$l?$l->[1]:"none",$h,$ok?"PASS":"FAIL" }
    elsif(/mem: suspended/){ $susp{all}++ } }
  printf "RESHOW_SUMMARY kind=%s resumes=%d pass=%d fail=%d suspended_tag_lines=%d\n",$kind,$full,$pass,$full-$pass,$susp{all}||0' "$1" "$2"
}

leg_reshow_session() { # kind
	local kind=$1 i f
	XENV=(CTERM_DEBUG_MEM=1 CTERM_DEBUG_FRAME_SUM=1)
	cde_start "reshow-$kind" "$kind"
	for i in 1 2 3 4; do
		spawn_win || { echo "spawn $i failed"; cde_stop; return 1; }
		sleep 1.5
		[ "$i" != 2 ] || { [ "$kind" != auto ] || assert_daemon_mode 2 || { cde_stop; return 1; }; }
	done
	sleep 2
	[ "$kind" != auto ] || assert_daemon_mode 4 || { cde_stop; return 1; }
	for i in -1 -1 -1 1 1 -1; do
		msg exec cycle-stack "$i" >/dev/null || echo "cycle-stack $i failed"
		sleep 2
	done
	if [ "$kind" = auto ]; then f=$T/state/crucible-term/daemon.log; else f=$T/log; fi
	grep -c 'frame-sum' "$f" | sed "s/^/RESHOW_LOGLINES kind=$kind frame_sum_lines=/"
	reshow_verdict "$f" "$kind" | tee -a "$OUT/g2-reshow.raw"
	cp "$f" "$OUT/logs/reshow-$kind.framesum.log" 2>/dev/null || true
	cde_stop
}

leg_reshow() {
	local k
	for k in auto standalone; do leg_reshow_session "$k" || echo "FAILED reshow $k"; done
}

leg_info_session() { # kind
	local kind=$1 i tg=big ns n pids tk0 tk1 t0 t1 hz
	XENV=()
	cde_start "info-$kind" "$kind"
	# 50 MB cat: time inside the terminal, 3 fresh windows
	printf '#!/bin/sh\ns=$(date +%%s%%N); cat "%s"; e=$(date +%%s%%N); echo $((e-s)) >> "%s/thr-%s.txt"\n' "$BIG" "$T" "$tg" >"$T/thr-$tg.sh"
	chmod +x "$T/thr-$tg.sh"
	for i in 1 2 3; do
		spawn_win exec run-in-terminal "$T/thr-$tg.sh" || spawn_win run-in-terminal "$T/thr-$tg.sh" || { echo "throughput spawn failed"; break; }
		for _ in $(seq 1 $((WAIT_S * 2))); do
			[ "$(cat "$T/thr-$tg.txt" 2>/dev/null | wc -l)" -ge "$i" ] && break
			sleep 0.5
		done
		sleep 1.5
		kill "$NEWPID" 2>/dev/null || true
		sleep 1
	done
	ns=$(cat "$T/thr-$tg.txt" 2>/dev/null | tr '\n' ' ' || true)
	echo "THR subj=$kind runs_ns=$ns median_s=$(awk '{printf "%.3f\n",$1/1e9}' "$T/thr-$tg.txt" 2>/dev/null | median)" | tee -a "$OUT/g2-info.raw"
	# idle CPU: two windows, G2_IDLE_S seconds
	CLIENTS=()
	spawn_win && spawn_win || { echo "idle spawn failed"; cde_stop; return 1; }
	sleep "$SETTLE"
	pids=("${CLIENTS[@]}")
	if [ "$kind" = auto ]; then assert_daemon_mode 2 || { cde_stop; return 1; }; pids=("$DPID" "${CLIENTS[@]}"); fi
	hz=$(getconf CLK_TCK)
	tk0=$(ticks_of "${pids[@]}")
	t0=$(now)
	sleep "$IDLE_S"
	t1=$(now)
	tk1=$(ticks_of "${pids[@]}")
	n=$(perl -e 'printf "%.3f", 100*(($ARGV[0]-$ARGV[1])/$ARGV[4])/($ARGV[2]-$ARGV[3])' "$tk1" "$tk0" "$t1" "$t0" "$hz")
	echo "IDLE_CPU subj=$kind windows=2 ticks=$((tk1 - tk0)) secs=$(perl -e 'printf "%.1f", $ARGV[0]-$ARGV[1]' "$t1" "$t0") pct_of_one_core=$n" | tee -a "$OUT/g2-info.raw"
	cde_stop
}

leg_info() {
	[ -s "$BIG" ] || die "missing $BIG (run scripts/g1/g1.sh once, or: seq 1 8000000 | head -c 52428800 > target/g1/50mb.txt)"
	local k
	for k in standalone auto; do leg_info_session "$k" || echo "FAILED info $k"; done
}

leg_smoke() {
	XENV=()
	cde_start smoke auto
	local i
	for i in 1 2 3; do spawn_win || die "spawn $i"; sleep 1.5; done
	sleep "$SETTLE"
	assert_daemon_mode 3
	echo "--- process tree below the compositor and the daemon"
	ps -o pid,ppid,etimes,args --ppid "$CPID" || true
	[ -z "$DPID" ] || ps -o pid,ppid,args --ppid "$DPID" || true
	cde_stop
}

# ---------------------------------------------------------------- reversed arrival end to end
E2E_FILE=""
e2e_craft() {
	mkdir -p "$T/state/cde/workspaces"
	E2E_FILE=$T/state/cde/workspaces/e2e.kdl
	cat >"$E2E_FILE" <<'KDL'
version 1
workspace "e2e" root="/tmp" {
    focused-pane 0
    split axis="horizontal" ratio=0.5 {
        pane focused=0 { terminal cwd="/tmp" command="sleep 1001" }
        pane focused=0 { terminal cwd="/tmp" command="sleep 1002" }
    }
}
KDL
	printf 'focused-output "nested"\noutput "nested" "e2e" focused="e2e"\n' >"$T/state/cde/session.kdl"
	cp "$E2E_FILE" "$OUT/logs/e2e-original.kdl"
}

# pid of a process whose cmdline (NUL -> space) contains $1 and whose exe basename is $2
find_proc() { # needle exe-basename
	local p
	for p in /proc/[0-9]*; do p=${p#/proc/}
		[ "$(basename "$(readlink "/proc/$p/exe" 2>/dev/null || true)")" = "$2" ] || continue
		tr '\0' ' ' <"/proc/$p/cmdline" 2>/dev/null | grep -qF -- "$1" || continue
		echo "$p"
	done
}

# commands of the terminal records in file order
saved_commands() { grep -o 'terminal [^}]*' "$1" | sed -n 's/.*command="\([^"]*\)".*/\1/p'; }

# start the nested CDE on a pre-crafted state dir (cde_start wipes its scratch, so write the state after the dir exists and before the compositor runs)
e2e_start_with_state() { # attempt
	local a=$1
	TAG=e2e-$a KIND=auto
	T=$W/$TAG
	rm -rf "$T"
	mkdir -p "$T/config/cde" "$T/config/crucible-term" "$T/config/foot" "$T/state/crucible-term" "$T/data" "$T/run"
	chmod 700 "$T/run"
	e2e_craft
	write_ct_config
	cat >"$T/config/cde/config.kdl" <<KDL
tiling {
    terminal gap=(px)$GAP ring=(px)2 ring-inset=(px)4 frame="#3a3a3a"
    terminal-args "-o" "pad={gap}x{gap} center" "-o" "mode=auto"
}
terminal "$CT" exec-flag="-e"
KDL
	PROGEXE=$(readlink -f "$CT")
	CLIENTS=() DPID=""
	run_on_launch g2 "$T" "$T/log" "${XENV[@]}" XDG_CONFIG_HOME="$T/config" XDG_STATE_HOME="$T/state" XDG_DATA_HOME="$T/data" XDG_RUNTIME_DIR="$T/run" WAYLAND_DISPLAY="$PARENT_WL" -- "$BIN" --winit || return 1
	CPID=$(real_cpid "$RUN_ON_PID")
	rec "$RUN_ON_PID"
	rec "$CPID"
	local i
	for i in $(seq 1 60); do
		ls "$T"/run/cde/*.sock >/dev/null 2>&1 && ls "$T"/run/wayland-* >/dev/null 2>&1 && break
		sleep 0.2
	done
	alive "$CPID" || { echo "compositor died: see $T/log"; tail -5 "$T/log"; return 1; }
	DISP=$(nested_display)
	[ "$T/run" != "$LIVE_RT" ] || die "nested XDG_RUNTIME_DIR is the live one"
	echo "== $TAG compositor pid $CPID display=$DISP runtime=$T/run delay=${DELAY_MS}ms"
}

leg_e2e_run() { # attempt; sets E2E_REVERSED=0/1; returns 1 on a harness failure
	local a=$1 p args i R1="" R2="" C1="" C2="" resp f out
	E2E_REVERSED=0
	XENV=(CTERM_DEBUG_OPEN_DELAY_MS="$DELAY_MS")
	e2e_start_with_state "$a" || return 1
	# wait for both restored wrappers under the daemon
	for i in $(seq 1 200); do
		DPID=$(daemon_pid || true)
		R1=$(find_proc "sleep 1001" crucible | head -1)
		R2=$(find_proc "sleep 1002" crucible | head -1)
		[ -n "$R1" ] && [ -n "$R2" ] && break
		sleep 0.2
	done
	echo "E2E attempt=$a daemon=$DPID wrappers R1=$R1 R2=$R2"
	if [ -z "$R1" ] || [ -z "$R2" ]; then
		echo "E2E FAIL: the restored wrappers did not both appear (see logs)"
		tail -20 "$T/log"
		tail -20 "$T/state/crucible-term/daemon.log" 2>/dev/null || true
		return 1
	fi
	rec "$DPID"
	# the thin clients: compositor children running cterm whose argv names the wrapper's command
	for i in $(seq 1 50); do
		for p in $(kids_of "$CPID"); do
			[ "$(readlink -f "/proc/$p/exe" 2>/dev/null)" = "$PROGEXE" ] || continue
			args=$(tr '\0' ' ' <"/proc/$p/cmdline")
			case $args in
			*"sleep 1001"*) C1=$p ;;
			*"sleep 1002"*) C2=$p ;;
			*) continue ;;
			esac
			rec "$p"
			CLIENTS+=("$p")
		done
		[ -n "$C1" ] && [ -n "$C2" ] && break
		CLIENTS=()
		sleep 0.2
	done
	echo "E2E clients C1=$C1 C2=$C2"
	assert_daemon_mode 2 || return 1
	for p in "$R1" "$R2"; do
		[ "$(awk '{print $4}' "/proc/$p/stat")" = "$DPID" ] || { echo "HARNESS FAILURE: wrapper $p is not a child of the daemon $DPID"; return 1; }
	done
	echo "E2E restore log:"
	grep -E 'open deferred|listening|open:' "$T/state/crucible-term/daemon.log" | sed 's/^/  daemon.log: /'
	if [ "$R2" -lt "$R1" ]; then
		E2E_REVERSED=1
		echo "E2E arrival: REVERSED (wrapper of slot 2 / sleep 1002 was forked first: R2=$R2 < R1=$R1)"
	else
		echo "E2E arrival: NOT reversed (R1=$R1 < R2=$R2): the first-connecting client was window 1 only in name; the delay hit the other order"
	fi
	sleep 3
	# (a) save: delete the restored file first, dirty the record with a divider move, save, compare slot -> command
	rm -f "$T/state/cde/workspaces/e2e.kdl"
	resp=$(msg exec resize right 2>&1 || true)
	echo "E2E resize: ${resp:-ok}"
	resp=$(msg save 2>&1 || true)
	echo "E2E (a) save response: ${resp:-ok}"
	sleep 2
	f=$T/state/cde/workspaces/e2e.kdl
	if [ ! -f "$f" ]; then
		echo "E2E (a) FAIL: save wrote no e2e.kdl; workspace dir has: $(ls "$T/state/cde/workspaces" | tr '\n' ' ')"
	else
		cp "$f" "$OUT/logs/e2e-saved-$a.kdl"
		echo "E2E (a) saved file:"
		sed 's/^/  | /' "$f"
		out=$(saved_commands "$f" | tr '\n' '|')
		echo "E2E (a) terminal records in file order: $out (expect 'sleep 1001|sleep 1002|' )"
		if [ "$out" = "sleep 1001|sleep 1002|" ] && ! grep -q '^ *app ' "$f"; then echo "E2E (a) PASS: each wrapper saved in its own original slot as a terminal record"; else echo "E2E (a) FAIL"; fi
	fi
	# (b) crucible mem lists the daemon
	out=$("$BIN" mem --pid "$CPID" 2>&1 || true)
	echo "E2E (b) crucible mem:"
	printf '%s\n' "$out" | sed 's/^/  | /'
	if printf '%s\n' "$out" | grep -qF 'cterm daemon (+2 windows)'; then echo "E2E (b) PASS: cterm daemon (+2 windows) row present"; else echo "E2E (b) FAIL: no 'cterm daemon (+2 windows)' row"; fi
	# (c) close-pid C1 closes only window 1
	resp=$(msg close-pid "$C1" 2>&1 || true)
	echo "E2E (c) close-pid $C1 response: ${resp:-<empty>}"
	for i in $(seq 1 50); do
		if ! alive "$C1" && ! alive "$R1"; then break; fi
		sleep 0.2
	done
	sleep 2
	echo "E2E (c) after: C1 alive=$(alive "$C1" && echo yes || echo no) R1 alive=$(alive "$R1" && echo yes || echo no) | C2 alive=$(alive "$C2" && echo yes || echo no) R2 alive=$(alive "$R2" && echo yes || echo no) daemon alive=$(alive "$DPID" && echo yes || echo no)"
	out=$("$BIN" mem --pid "$CPID" 2>&1 || true)
	printf '%s\n' "$out" | grep 'cterm daemon' | sed 's/^/  | after close: /' || true
	if ! alive "$C1" && ! alive "$R1" && alive "$C2" && alive "$R2" && alive "$DPID"; then echo "E2E (c) PASS: only window 1 closed"; else echo "E2E (c) FAIL"; fi
	return 0
}

leg_e2e() {
	local a
	: >"$OUT/g2-e2e.raw"
	for a in 1 2 3; do
		E2E_REVERSED=0
		{ leg_e2e_run "$a" || echo "E2E attempt $a: harness failure"; } >"$OUT/logs/e2e-run-$a.txt" 2>&1
		echo "E2E attempt=$a reversed=$E2E_REVERSED" >>"$OUT/logs/e2e-run-$a.txt"
		tee -a "$OUT/g2-e2e.raw" <"$OUT/logs/e2e-run-$a.txt"
		cp "$T/state/crucible-term/daemon.log" "$OUT/logs/e2e-$a.daemon.log" 2>/dev/null || true
		cp "$T/log" "$OUT/logs/e2e-$a.compositor.log" 2>/dev/null || true
		cde_stop
		if [ "$E2E_REVERSED" = 1 ]; then break; fi
	done
}

# ---------------------------------------------------------------- summary
leg_summarize() {
	perl -e '
  sub med { my @a=sort {$a<=>$b} @_; return "NA" unless @a; my $n=@a; return $n%2 ? $a[($n-1)/2] : ($a[$n/2-1]+$a[$n/2])/2 }
  sub kv { my %h; $h{$1}=$2 while $_[0]=~/(\w+)=(\S+)/g; \%h }
  my $dir=shift;
  my (%mem,%ratio);
  if(open(F,"<","$dir/g2-mem.raw")){ while(<F>){ next unless /^(MEM|DMEM|CMEM) (.*)/; my ($t,$rest)=($1,$2); my $h=kv($rest); $mem{$t}{$h->{subj}}{$h->{n}}{$h->{batch}}=$h;
      if($t eq "MEM" && $h->{subj} eq "foot" && $h->{n}==1 && $h->{shm_rss}>0){ $ratio{$h->{batch}}=$h->{shm_pss}/$h->{shm_rss} } } close F }
  my $defratio = %ratio ? med(values %ratio) : 0.747;
  sub norm { my($h,$b)=@_; my $r=$ratio{$b}//$defratio; return $h->{nonshm}+$h->{shm_rss}*$r }
  sub nmed { my($t,$s,$n)=@_; my $x=$mem{$t}{$s}{$n}; return "NA" unless $x; return med(map { norm($x->{$_},$_) } keys %$x) }
  sub rmed { my($t,$s,$n,$f)=@_; my $x=$mem{$t}{$s}{$n}; return "NA" unless $x; return med(map { $x->{$_}{$f} } keys %$x) }
  sub slope { my($t,$s,$lo,$hi)=@_; my @v; for my $b (keys %{$mem{$t}{$s}{$lo}||{}}){ next unless $mem{$t}{$s}{$hi}{$b}; push @v,(norm($mem{$t}{$s}{$hi}{$b},$b)-norm($mem{$t}{$s}{$lo}{$b},$b))/($hi-$lo) } return @v ? med(@v) : "NA" }
  my ($lo,$hi)=@ARGV[0,1];
  printf "G2 RESULT (shm PSS normalised: nonshm PSS + shm Rss x foot shm PSS/Rss, per batch; ratio median %.4f over %d batches)\n",$defratio,scalar(keys %ratio);
  my $foot=nmed("MEM","foot",1); my $sa=nmed("MEM","standalone",1); my $au=nmed("MEM","auto",1);
  if($foot ne "NA" && $sa ne "NA"){ printf "leg (i)   standalone window+shell %.0f kB vs foot %.0f kB: %+.1f%% (threshold <= +10%%): %s\n",$sa,$foot,100*($sa/$foot-1),($sa<=1.10*$foot?"PASS":"FAIL") } else { print "leg (i)   not measured\n" }
  my $sl=slope("MEM","auto",$lo,$hi);
  if($sl ne "NA"){ printf "leg (ii)  auto marginal per window, slope %d->%d windows: %.0f kB = %.2f MiB (threshold <= 10 MiB): %s\n",$lo,$hi,$sl,$sl/1024,($sl<=10240?"PASS":"FAIL") } else { print "leg (ii)  not measured\n" }
  my $ss=slope("MEM","standalone",$lo,$hi); my $fs=slope("MEM","foot",$lo,$hi);
  printf "  info    standalone slope %s kB (%s MiB) per window, foot slope %s kB (%s MiB)\n",map { $_ eq "NA" ? ("NA","NA") : (sprintf("%.0f",$_),sprintf("%.2f",$_/1024)) } ($ss,$fs);
  if($foot ne "NA" && $au ne "NA"){ printf "leg (iii) auto 1 daemon(incl. baseline)+client+shell %.0f kB vs foot %.0f kB: %+.1f%% (threshold <= +5%%): %s\n",$au,$foot,100*($au/$foot-1),($au<=1.05*$foot?"PASS":"FAIL") } else { print "leg (iii) not measured\n" }
  my $d0=nmed("DMEM","auto-daemon",0); my $d1=nmed("DMEM","auto-daemon",1);
  printf "  info    daemon idle (0 windows) %s kB; daemon with 1 window %s kB; incremental (daemon n=1 minus idle) %s kB\n",$d0,$d1,($d0 ne "NA" && $d1 ne "NA") ? sprintf("%.0f",$d1-$d0) : "NA";
  printf "  info    raw medians (nonshm / shm_pss / shm_rss kB): foot1 %s/%s/%s standalone1 %s/%s/%s auto1 %s/%s/%s\n",(map { my $s=$_; (rmed("MEM",$s,1,"nonshm"),rmed("MEM",$s,1,"shm_pss"),rmed("MEM",$s,1,"shm_rss")) } qw(foot standalone auto));
  for my $s (qw(foot standalone auto)) { printf "  info    %-10s total normalised kB at n=1/%d/%d: %s / %s / %s\n",$s,$lo,$hi,map { my $v=nmed("MEM",$s,$_); $v eq "NA" ? $v : sprintf("%.0f",$v) } (1,$lo,$hi) }
  my %ff;
  if(open(F,"<","$dir/g2-ff.raw")){ while(<F>){ next unless /^FF_MEDIAN (.*)/; my $rest=$1; my $h=kv($rest); push @{$ff{$h->{subj}}},$h->{ms} if $h->{ms} ne "NA" } close F }
  my $fa=med(@{$ff{auto}||[]}); my $fb=med(@{$ff{"standalone-wl"}||[]}); my $fc=med(@{$ff{"foot-wl"}||[]});
  printf "first frame (median of batch medians): auto warm daemon %s ms vs G1 64.2 ms: %s; vs same-batch standalone %s ms: %s; foot %s ms (info)\n",$fa,($fa ne "NA" && $fa<=64.2?"PASS":"FAIL"),$fb,($fa ne "NA" && $fb ne "NA" && $fa<=$fb?"PASS":"FAIL"),$fc;
  for my $k (qw(auto standalone-wl foot-wl)){ printf "  info    first-frame batch medians %s: %s\n",$k,join(" ",@{$ff{$k}||[]}) }
  if(open(F,"<","$dir/g2-reshow.raw")){ while(<F>){ print "$_" if /^RESHOW/ } close F }
  if(open(F,"<","$dir/g2-info.raw")){ while(<F>){ print "$_" if /^(THR|IDLE_CPU)/ } close F }
' "$OUT" "$N_LO" "$N_HI" | tee "$OUT/g2-summary.txt"
}

leg_rsummarize() {
	perl -e '
  sub med { my @a=sort {$a<=>$b} @_; return "NA" unless @a; my $n=@a; return $n%2 ? $a[($n-1)/2] : ($a[$n/2-1]+$a[$n/2])/2 }
  sub kv { my %h; $h{$1}=$2 while $_[0]=~/(\w+)=(\S+)/g; \%h }
  my ($dir,$lo,$hi)=@ARGV;
  print "G2 RE-MEASUREMENT SUMMARY\n";
  my (%ff,@order,%seen);
  if(open(F,"<","$dir/g2-ff.raw")){ while(<F>){
    if(/^SUBJECT (.*)/){ my $l=$1; print "subject: $l\n" unless $seen{$l}++ }
    next unless /^FF_MEDIAN (.*)/; my $rest=$1; my $h=kv($rest); push @order,$h->{subj} unless $ff{$h->{subj}}; push @{$ff{$h->{subj}}},$h->{ms} } close F }
  print "first frame, batch medians of 5 (ms) and median of batch medians:\n";
  for my $s (@order){ my @v=grep { $_ ne "NA" } @{$ff{$s}}; printf "  ff %-14s %s => %s\n",$s,join(" / ",@{$ff{$s}}),med(@v) }
  my (%mem,%ratio);
  if(open(F,"<","$dir/g2-mem.raw")){ while(<F>){ next unless /^(MEM|DMEM|CMEM) (.*)/; my ($t,$rest)=($1,$2); my $h=kv($rest); $mem{$t}{$h->{subj}}{$h->{n}}{$h->{batch}}=$h;
      if($t eq "MEM" && $h->{subj} eq "foot" && $h->{n}==1 && $h->{shm_rss}>0){ $ratio{$h->{batch}}=$h->{shm_pss}/$h->{shm_rss} } } close F }
  my $defratio = %ratio ? med(values %ratio) : 0.747;
  sub norm { my($h,$b)=@_; my $r=$ratio{$b}//$defratio; return $h->{nonshm}+$h->{shm_rss}*$r }
  sub bat { my($t,$s,$n)=@_; my $x=$mem{$t}{$s}{$n}; return () unless $x; return map { [$_,norm($x->{$_},$_)] } sort keys %$x }
  sub nmed { my @b=bat(@_); return @b ? med(map { $_->[1] } @b) : "NA" }
  sub slope { my($t,$s)=@_; my @v; for my $b (keys %{$mem{$t}{$s}{$lo}||{}}){ next unless $mem{$t}{$s}{$hi}{$b}; push @v,(norm($mem{$t}{$s}{$hi}{$b},$b)-norm($mem{$t}{$s}{$lo}{$b},$b))/($hi-$lo) } return @v ? med(@v) : "NA" }
  printf "leg (iii) like-for-like, n=1, total normalised kB (shm ratio %.4f from foot per batch):\n",$defratio;
  my %m1;
  for my $s (qw(foot foot-server standalone auto)){ my @b=bat("MEM",$s,1); $m1{$s}=\@b; printf "  mem %-12s %s => %s\n",$s,join(" / ",map { sprintf("%.0f",$_->[1]) } @b),(@b ? sprintf("%.0f",nmed("MEM",$s,1)) : "NA") }
  my ($fs,$au,$ft)=(nmed("MEM","foot-server",1),nmed("MEM","auto",1),nmed("MEM","foot",1));
  if($fs ne "NA" && $au ne "NA"){
    my @pb; for my $i (0..$#{$m1{auto}}){ my $a=$m1{auto}[$i][1]; my ($f)=grep { $_->[0] eq $m1{auto}[$i][0] } @{$m1{"foot-server"}}; push @pb,100*($a/$f->[1]-1) if $f }
    printf "  auto vs foot-server: %+.1f%% on medians (%.0f vs %.0f); per batch %s\n",100*($au/$fs-1),$au,$fs,join(" / ",map { sprintf("%+.1f%%",$_) } @pb);
    printf "  threshold (<= foot-server + 5%% = %.0f kB): %s\n",1.05*$fs,($au<=1.05*$fs?"PASS":"FAIL");
  } else { print "  auto vs foot-server: not measured\n" }
  if($ft ne "NA" && $au ne "NA"){ printf "  auto vs standalone foot: %+.1f%% (%.0f vs %.0f)\n",100*($au/$ft-1),$au,$ft }
  for my $s (qw(foot-server)){ my @b=bat("DMEM","$s-daemon",0); if(@b){ my $x=$mem{DMEM}{"$s-daemon"}{0}; printf "  foot-server idle, zero windows, nonshm kB: %s => %s\n",join(" / ",map { $x->{$_}{nonshm} } sort keys %$x),med(map { $x->{$_}{nonshm} } keys %$x) } }
  for my $s (qw(foot foot-server standalone auto)){ my $v=slope("MEM",$s); printf "  slope %d->%d windows, %-11s %s kB (%s MiB) per window\n",$lo,$hi,$s,($v eq "NA" ? ("NA","NA") : (sprintf("%.0f",$v),sprintf("%.2f",$v/1024))) }
  for my $s (qw(foot foot-server standalone auto)){ printf "  total normalised kB %-11s n=1/%d/%d: %s\n",$s,$lo,$hi,join(" / ",map { my $v=nmed("MEM",$s,$_); $v eq "NA" ? $v : sprintf("%.0f",$v) } (1,$lo,$hi)) }
  my ($nc,$lmax,$lmin,$waits,$bad)=(0,0,1e9,0,0); my %pmax;
  for my $f (qw(g2-cond.raw g2-ff.raw g2-mem.raw)){ if(open(F,"<","$dir/$f")){ while(<F>){
    if(/^COND_WAIT .*waited_s=(\d+)/){ if($1>0){ $waits++; print "$_" } next }
    next unless /^COND label=/; $nc++;
    if(/loadavg="([\d.]+)/){ $lmax=$1 if $1>$lmax; $lmin=$1 if $1<$lmin }
    for my $k (qw(cpu mem io)){ if(/${k}_some_avg10_avg60=([\d.]+),([\d.]+)/){ $pmax{"$k avg10"}=$1 if $1>($pmax{"$k avg10"}//0); $pmax{"$k avg60"}=$2 if $2>($pmax{"$k avg60"}//0) } }
    $bad++ unless /outputs="[^"]*enabled\/On/ } close F } }
  printf "conditions over %d COND lines: loadavg(1m) min %.2f max %.2f; PSI some max %s; waits for CPU PSI: %d; lines without an enabled/On output: %d\n",$nc,$lmin,$lmax,join(", ",map { "$_ $pmax{$_}" } sort keys %pmax),$waits,$bad;
' "$OUT" "$N_LO" "$N_HI" | tee "$OUT/remeasure-summary.txt"
}

[ -x "$CT" ] || die "missing $CT (cargo build --release)"
[ -x "$BIN" ] || die "missing $BIN"
[ -x "$FOOT" ] || die "missing $FOOT"
# The nested winit window needs frame callbacks from the parent compositor; with every output DPMS-off it never gets any and its main loop stalls.
display_awake() {
	local d any=1
	for d in /sys/class/drm/card*-*; do
		if [ "$(cat "$d/status" 2>/dev/null)" = connected ] && [ "$(cat "$d/enabled" 2>/dev/null)" = enabled ]; then any=0; fi
	done
	return $any
}
needs_display=0
for leg in "${LEGS[@]}"; do [ "$leg" = summarize ] || needs_display=1; done
if [ "$needs_display" = 1 ] && [ "${G2_SKIP_DISPLAY_CHECK:-0}" != 1 ]; then
	waited=0
	while ! display_awake && [ "$waited" -lt "${G2_WAIT_DISPLAY_S:-0}" ]; do sleep 5; waited=$((waited + 5)); done
	if ! display_awake; then
		echo "g2.sh: BLOCKED: every connected output of the live session is disabled (DPMS off), so the parent compositor sends the nested window no frame callbacks and the nested crucible stalls. Wake the display (or set G2_WAIT_DISPLAY_S=N to wait, G2_SKIP_DISPLAY_CHECK=1 to override)." >&2
		exit 3
	fi
fi
mkdir -p "$W"
: >"$W/pids"
echo "g2.sh: crucible $("$BIN" --build) | cterm $("$CT" --version | head -1) | $("$FOOT" --version 2>&1 | head -1)"
for leg in "${LEGS[@]}"; do
	echo "=== leg $leg ($(date +%T))"
	"leg_$leg"
done
